/* Build a ClientHello: record sequence, message sequence, session ID length, cookie, and
   the first byte of the random. Returns the record length.  */
static UINT clienthello_build(UCHAR *buffer, USHORT sequence_high, ULONG sequence_low, UINT message_sequence,
                              UINT session_id_length, const UCHAR *cookie, UINT cookie_length, UCHAR random_first)
{
UINT body_length = 35 + session_id_length + 1 + cookie_length + sizeof(clienthello_suites);
UINT position;

    buffer[0] = 0x16;
    buffer[1] = 0xfe;
    buffer[2] = 0xfd;
    buffer[3] = 0;
    buffer[4] = 0;
    buffer[5] = (UCHAR)(sequence_high >> 8);
    buffer[6] = (UCHAR)sequence_high;
    buffer[7] = (UCHAR)(sequence_low >> 24);
    buffer[8] = (UCHAR)(sequence_low >> 16);
    buffer[9] = (UCHAR)(sequence_low >> 8);
    buffer[10] = (UCHAR)sequence_low;
    buffer[11] = (UCHAR)((body_length + 12) >> 8);
    buffer[12] = (UCHAR)(body_length + 12);
    buffer[13] = 0x01;
    buffer[14] = 0;
    buffer[15] = (UCHAR)(body_length >> 8);
    buffer[16] = (UCHAR)body_length;
    buffer[17] = (UCHAR)(message_sequence >> 8);
    buffer[18] = (UCHAR)message_sequence;
    buffer[19] = 0;
    buffer[20] = 0;
    buffer[21] = 0;
    buffer[22] = 0;
    buffer[23] = (UCHAR)(body_length >> 8);
    buffer[24] = (UCHAR)body_length;
    buffer[25] = 0xfe;
    buffer[26] = 0xfd;
    memcpy(&buffer[27], clienthello_random, sizeof(clienthello_random));
    buffer[27] = random_first;
    buffer[59] = (UCHAR)session_id_length;
    memset(&buffer[60], 0xA5, session_id_length);
    position = 60 + session_id_length;
    buffer[position] = (UCHAR)cookie_length;
    position++;
    memcpy(&buffer[position], cookie, cookie_length);
    position += cookie_length;
    memcpy(&buffer[position], clienthello_suites, sizeof(clienthello_suites));
    position += sizeof(clienthello_suites);

    return(position);
}

/* HMAC-SHA256 computed with the crypto library's HMAC method, independently of the
   server's own construction.  */
static VOID hmac_sha256(const UCHAR *key, UINT key_length, UCHAR *data, UINT length, UCHAR *output)
{
UINT status;

    status = crypto_method_hmac_sha256.nx_crypto_operation(NX_CRYPTO_AUTHENTICATE, NX_NULL, &crypto_method_hmac_sha256,
                                                           (UCHAR *)key, key_length << 3, data, length, NX_NULL,
                                                           output, 32, hmac_metadata, sizeof(hmac_metadata),
                                                           NX_NULL, NX_NULL);
    if (status)
    {
        ERROR_COUNTER();
    }
}

/* The cookie expected for a ClientHello: key identifier, then HMAC-SHA256 under secret of
   the peer address and ports, the ClientHello fields up to the session ID, and the cipher
   suite and compression lists.  */
static VOID cookie_expected(const UCHAR *secret, UCHAR key_id, NXD_ADDRESS *address, UINT remote_port,
                            UINT local_port, const UCHAR *clienthello, UCHAR *cookie)
{
UCHAR data[1 + 16 + 4 + 35 + 32 + CLIENTHELLO_MAX];
UCHAR mac[32];
UINT  length = 0;
UINT  session_id_length = clienthello[59];
UINT  suites_offset;
UINT  suites_end;
UINT  i;

    data[length++] = (UCHAR)address -> nxd_ip_version;
    if (address -> nxd_ip_version == NX_IP_VERSION_V6)
    {
        for (i = 0; i < 4; i++)
        {
            data[length++] = (UCHAR)(address -> nxd_ip_address.v6[i] >> 24);
            data[length++] = (UCHAR)(address -> nxd_ip_address.v6[i] >> 16);
            data[length++] = (UCHAR)(address -> nxd_ip_address.v6[i] >> 8);
            data[length++] = (UCHAR)address -> nxd_ip_address.v6[i];
        }
    }
    else
    {
        data[length++] = (UCHAR)(address -> nxd_ip_address.v4 >> 24);
        data[length++] = (UCHAR)(address -> nxd_ip_address.v4 >> 16);
        data[length++] = (UCHAR)(address -> nxd_ip_address.v4 >> 8);
        data[length++] = (UCHAR)address -> nxd_ip_address.v4;
    }
    data[length++] = (UCHAR)(remote_port >> 8);
    data[length++] = (UCHAR)remote_port;
    data[length++] = (UCHAR)(local_port >> 8);
    data[length++] = (UCHAR)local_port;

    memcpy(&data[length], &clienthello[25], 35 + session_id_length);
    length += 35 + session_id_length;

    suites_offset = 61 + session_id_length + clienthello[60 + session_id_length];
    suites_end = suites_offset + 2 + (((UINT)clienthello[suites_offset] << 8) | clienthello[suites_offset + 1]);
    suites_end += 1 + clienthello[suites_end];
    memcpy(&data[length], &clienthello[suites_offset], suites_end - suites_offset);
    length += suites_end - suites_offset;

    hmac_sha256(secret, 32, data, length, mac);
    cookie[0] = key_id;
    memcpy(&cookie[1], mac, NX_SECURE_DTLS_COOKIE_LENGTH - 1);
}

/* Send a record from the raw socket to the server.  */
static VOID raw_send(const UCHAR *data, UINT length)
{
NX_PACKET  *packet_ptr;
NXD_ADDRESS server_address;
UINT        status;

    server_address.nxd_ip_version = NX_IP_VERSION_V4;
    server_address.nxd_ip_address.v4 = TEST_SERVER_IP_ADDRESS;

    status = nx_packet_allocate(&client_pool, &packet_ptr, NX_UDP_PACKET, NX_WAIT_FOREVER);
    status |= nx_packet_data_append(packet_ptr, (VOID *)data, length, &client_pool, NX_NO_WAIT);
    status |= nxd_udp_socket_send(&raw_socket, packet_ptr, &server_address, SERVER_PORT);
    if (status)
    {
        ERROR_COUNTER();
    }
}

/* Receive one datagram on the raw socket. Returns its length, or 0 if none arrives.  */
static UINT raw_receive(UCHAR *buffer, UINT size, ULONG wait_option)
{
NX_PACKET *packet_ptr;
ULONG      length = 0;

    if (nx_udp_socket_receive(&raw_socket, &packet_ptr, wait_option) == NX_SUCCESS)
    {
        if (nx_packet_data_extract_offset(packet_ptr, 0, buffer, size, &length))
        {
            ERROR_COUNTER();
        }
        nx_packet_release(packet_ptr);
    }

    return((UINT)length);
}

/* Give a session the raw socket as its peer, as the DTLS server does when it allocates
   the session.  */
static VOID session_peer_set(VOID)
{
    server_session -> nx_secure_dtls_remote_ip_address.nxd_ip_version = NX_IP_VERSION_V4;
    server_session -> nx_secure_dtls_remote_ip_address.nxd_ip_address.v4 = TEST_CLIENT_IP_ADDRESS;
    server_session -> nx_secure_dtls_remote_port = RAW_PORT;
    server_session -> nx_secure_dtls_local_port = SERVER_PORT;
}

/* Send a ClientHello and return the cookie of the HelloVerifyRequest answering it.  */
static VOID clienthello_expect_hvr(const UCHAR *clienthello, UINT length, UCHAR *cookie)
{
UCHAR reply[256];
UINT  reply_length;

    raw_send(clienthello, length);
    reply_length = raw_receive(reply, sizeof(reply), NX_IP_PERIODIC_RATE);
    if ((reply_length != 25 + 3 + NX_SECURE_DTLS_COOKIE_LENGTH) || (reply[0] != 0x16) ||
        (reply[13] != NX_SECURE_TLS_HELLO_VERIFY_REQUEST) || (reply[27] != NX_SECURE_DTLS_COOKIE_LENGTH))
    {
        ERROR_COUNTER();
        memset(cookie, 0, NX_SECURE_DTLS_COOKIE_LENGTH);
        return;
    }
    memcpy(cookie, &reply[28], NX_SECURE_DTLS_COOKIE_LENGTH);
}

/* The 32-byte secret NX_RAND yields after seeding.  */
static VOID random_secret(UINT seed, UCHAR *secret, UINT length)
{
UINT i;
UINT random_value;

    srand(seed);
    for (i = 0; i < length; i += 4)
    {
        random_value = (UINT)rand();
        secret[i] = (UCHAR)(random_value >> 24);
        secret[i + 1] = (UCHAR)(random_value >> 16);
        secret[i + 2] = (UCHAR)(random_value >> 8);
        secret[i + 3] = (UCHAR)random_value;
    }
}

/* Check a ClientHello built by clienthello_build as the session does.  */
static UINT direct_verify(NX_SECURE_DTLS_SESSION *session, UCHAR *clienthello, UCHAR *verified)
{
UINT session_id_length = clienthello[59];
UINT cookie_length = clienthello[60 + session_id_length];

    return(_nx_secure_dtls_session_cookie_verify(session, &clienthello[25], 35 + session_id_length,
                                                 &clienthello[61 + session_id_length + cookie_length],
                                                 sizeof(clienthello_suites),
                                                 &clienthello[61 + session_id_length], cookie_length, verified));
}

/* Expect a session check with the given status and outcome.  */
static VOID verify_expect(UCHAR *clienthello, UINT expected_status, UCHAR expected_verified, UINT line)
{
UCHAR verified = 0xFF;

    if ((direct_verify(server_session, clienthello, &verified) != expected_status) || (verified != expected_verified))
    {
        __ERROR_COUNTER(__FILE__, line);
    }
}

/* Through the network: the DTLS server allocates the session, its cookie secret is then
   replaced, and the session answers the ClientHello it holds with a HelloVerifyRequest
   under the new secret. A seeded NX_RAND does not reproduce that cookie; tampered or
   mismatched cookies are answered with another HelloVerifyRequest, and the valid one with
   a ServerHello.  */
static VOID test_handshake(VOID)
{
UCHAR       clienthello[CLIENTHELLO_MAX];
UCHAR       cookie[NX_SECURE_DTLS_COOKIE_LENGTH];
UCHAR       reissued[NX_SECURE_DTLS_COOKIE_LENGTH];
UCHAR       altered[NX_SECURE_DTLS_COOKIE_LENGTH];
UCHAR       secret[32];
UCHAR       expected[NX_SECURE_DTLS_COOKIE_LENGTH];
UCHAR       reply[1500];
UINT        length;
UINT        reply_length;
NXD_ADDRESS address;

    address.nxd_ip_version = NX_IP_VERSION_V4;
    address.nxd_ip_address.v4 = TEST_CLIENT_IP_ADDRESS;

    /* The DTLS server's cookie exchange allocates the session.  */
    tx_time_set(1000);
    length = clienthello_build(clienthello, 0, 0, 0, 0, NX_NULL, 0, 0x32);
    clienthello_expect_hvr(clienthello, length, cookie);
    length = clienthello_build(clienthello, 0, 1, 1, 0, cookie, sizeof(cookie), 0x32);
    raw_send(clienthello, length);
    if (tx_semaphore_get(&semaphore_connect, NX_IP_PERIODIC_RATE))
    {
        ERROR_COUNTER();
        return;
    }

    /* Two lifetimes pass before the session processes the ClientHello, which its server
       did not verify: the cookie's secret is no longer accepted.  */
    server_session -> nx_secure_dtls_cookie_verified = NX_FALSE;
    tx_time_set(1000 + 2 * LIFETIME);
    srand(RANDOM_SEED);
    tx_thread_resume(&server_thread);
    reply_length = raw_receive(reply, sizeof(reply), NX_IP_PERIODIC_RATE);
    if ((reply_length != 25 + 3 + NX_SECURE_DTLS_COOKIE_LENGTH) ||
        (reply[13] != NX_SECURE_TLS_HELLO_VERIFY_REQUEST) || (reply[27] != NX_SECURE_DTLS_COOKIE_LENGTH))
    {
        ERROR_COUNTER();
    }
    memcpy(cookie, &reply[28], sizeof(cookie));

    /* Not raw NX_RAND output a seeded generator reproduces, but an HMAC under a secret
       drawn from it, as the server's next secret.  */
    random_secret(RANDOM_SEED, secret, sizeof(secret));
    if (memcmp(&cookie[1], secret, 20) == 0)
    {
        ERROR_COUNTER();
    }
    cookie_expected(secret, 1, &address, RAW_PORT, SERVER_PORT, clienthello, expected);
    if (memcmp(cookie, expected, sizeof(expected)))
    {
        ERROR_COUNTER();
    }

    /* One byte of the MAC altered.  */
    memcpy(altered, cookie, sizeof(altered));
    altered[7] ^= 0x80;
    length = clienthello_build(clienthello, 0, 2, 2, 0, altered, sizeof(altered), 0x32);
    clienthello_expect_hvr(clienthello, length, reissued);
    if (memcmp(reissued, cookie, sizeof(cookie)))
    {
        ERROR_COUNTER();
    }

    /* The cookie returned with a different random.  */
    length = clienthello_build(clienthello, 0, 3, 3, 0, cookie, sizeof(cookie), 0x33);
    clienthello_expect_hvr(clienthello, length, reissued);
    if (memcmp(reissued, cookie, sizeof(cookie)) == 0)
    {
        ERROR_COUNTER();
    }

    /* A truncated cookie.  */
    length = clienthello_build(clienthello, 0, 4, 4, 0, cookie, sizeof(cookie) - 1, 0x32);
    clienthello_expect_hvr(clienthello, length, reissued);

    /* The valid cookie.  */
    length = clienthello_build(clienthello, 0, 5, 5, 0, cookie, sizeof(cookie), 0x32);
    raw_send(clienthello, length);
    reply_length = raw_receive(reply, sizeof(reply), NX_IP_PERIODIC_RATE);
    if ((reply_length < 25) || (reply[0] != 0x16) || (reply[13] != 0x02))
    {
        ERROR_COUNTER();
    }

    if (tx_semaphore_get(&semaphore_server, 30 * NX_IP_PERIODIC_RATE) || (server_status == NX_SUCCESS))
    {
        ERROR_COUNTER();
    }
    while (raw_receive(reply, sizeof(reply), NX_IP_PERIODIC_RATE / 5))
    {
    }
}

/* Directly: the session accepts the server's cookie for its peer and ClientHello, under
   the current secret or, for one more lifetime, the previous one.  */
static VOID test_direct(VOID)
{
UCHAR       clienthello[CLIENTHELLO_MAX];
UCHAR       cookie[NX_SECURE_DTLS_COOKIE_LENGTH];
UCHAR       altered[NX_SECURE_DTLS_COOKIE_LENGTH];
UCHAR       expected[NX_SECURE_DTLS_COOKIE_LENGTH];
UCHAR       secret[32];
UCHAR       master[32];
UCHAR       counter[4] = {0, 0, 0, 0};
UCHAR       verified;
UINT        length;
UINT        i;
ULONG       start = 2000000;
NXD_ADDRESS address;

    address.nxd_ip_version = NX_IP_VERSION_V4;
    address.nxd_ip_address.v4 = TEST_CLIENT_IP_ADDRESS;
    nx_secure_dtls_session_reset(server_session);
    session_peer_set();

    /* A cookie issued under a secret drawn from NX_RAND.  */
    nx_secure_dtls_server_cookie_secret_set(&dtls_server, NX_NULL, 0);
    tx_time_set(start);
    random_secret(RANDOM_SEED + 1, secret, sizeof(secret));
    srand(RANDOM_SEED + 1);
    length = clienthello_build(clienthello, 0, 0, 0, 0, NX_NULL, 0, 0x32);
    verify_expect(clienthello, NX_SUCCESS, NX_FALSE, __LINE__);
    memcpy(cookie, server_session -> nx_secure_dtls_cookie, sizeof(cookie));
    cookie_expected(secret, 0, &address, RAW_PORT, SERVER_PORT, clienthello, expected);
    if (memcmp(cookie, expected, sizeof(expected)) ||
        (server_session -> nx_secure_dtls_cookie_length != NX_SECURE_DTLS_COOKIE_LENGTH))
    {
        ERROR_COUNTER();
    }

    length = clienthello_build(clienthello, 0, 1, 1, 0, cookie, sizeof(cookie), 0x32);
    verify_expect(clienthello, NX_SUCCESS, NX_TRUE, __LINE__);

    /* Another client port, address or server port.  */
    server_session -> nx_secure_dtls_remote_port = RAW_PORT + 1;
    verify_expect(clienthello, NX_SUCCESS, NX_FALSE, __LINE__);
    session_peer_set();
    server_session -> nx_secure_dtls_remote_ip_address.nxd_ip_address.v4 = TEST_CLIENT_IP_ADDRESS + 1;
    verify_expect(clienthello, NX_SUCCESS, NX_FALSE, __LINE__);
    session_peer_set();
    server_session -> nx_secure_dtls_local_port = SERVER_PORT + 1;
    verify_expect(clienthello, NX_SUCCESS, NX_FALSE, __LINE__);
    session_peer_set();

    /* An unknown key identifier, and a truncated cookie.  */
    memcpy(altered, cookie, sizeof(altered));
    altered[0] = 2;
    length = clienthello_build(clienthello, 0, 1, 1, 0, altered, sizeof(altered), 0x32);
    verify_expect(clienthello, NX_SUCCESS, NX_FALSE, __LINE__);
    length = clienthello_build(clienthello, 0, 1, 1, 0, cookie, sizeof(cookie) - 1, 0x32);
    verify_expect(clienthello, NX_SUCCESS, NX_FALSE, __LINE__);

    /* Another cipher suite list.  */
    length = clienthello_build(clienthello, 0, 1, 1, 0, cookie, sizeof(cookie), 0x32);
    clienthello[length - 3] = 0x0a;
    verify_expect(clienthello, NX_SUCCESS, NX_FALSE, __LINE__);

    /* After one lifetime the cookie is under the previous secret and still accepted, and a
       new one is issued under the current secret.  */
    tx_time_set(start + LIFETIME);
    length = clienthello_build(clienthello, 0, 1, 1, 0, cookie, sizeof(cookie), 0x32);
    verify_expect(clienthello, NX_SUCCESS, NX_TRUE, __LINE__);
    length = clienthello_build(clienthello, 0, 0, 0, 0, NX_NULL, 0, 0x32);
    verify_expect(clienthello, NX_SUCCESS, NX_FALSE, __LINE__);
    if (server_session -> nx_secure_dtls_cookie[0] != 1)
    {
        ERROR_COUNTER();
    }

    /* Two lifetimes later the previous secret is no longer accepted.  */
    tx_time_set(start + 3 * LIFETIME);
    length = clienthello_build(clienthello, 0, 1, 1, 0, cookie, sizeof(cookie), 0x32);
    verify_expect(clienthello, NX_SUCCESS, NX_FALSE, __LINE__);

    /* A cookie under a secret derived from the server's application secret.  */
    for (i = 0; i < sizeof(master); i++)
    {
        master[i] = (UCHAR)(0x80 + i);
    }
    nx_secure_dtls_server_cookie_secret_set(&dtls_server, master, sizeof(master));
    length = clienthello_build(clienthello, 0, 0, 0, 0, NX_NULL, 0, 0x32);
    verify_expect(clienthello, NX_SUCCESS, NX_FALSE, __LINE__);
    hmac_sha256(master, sizeof(master), counter, sizeof(counter), secret);
    cookie_expected(secret, 0, &address, RAW_PORT, SERVER_PORT, clienthello, expected);
    if (memcmp(server_session -> nx_secure_dtls_cookie, expected, sizeof(expected)))
    {
        ERROR_COUNTER();
    }
    nx_secure_dtls_server_cookie_secret_set(&dtls_server, NX_NULL, 0);

    /* A session without a DTLS server has no cookie secret.  */
    if ((direct_verify(&plain_session, clienthello, &verified) != NX_SECURE_TLS_SESSION_UNINITIALIZED) ||
        (verified != NX_FALSE))
    {
        ERROR_COUNTER();
    }
}

/* A cookie MAC that cannot be computed fails the ClientHello.  */
static VOID test_crypto_failures(VOID)
{
UCHAR                 clienthello[CLIENTHELLO_MAX];
UCHAR                 master[32];
UINT                  length;
NX_SECURE_TLS_CRYPTO *original_table = server_session -> nx_secure_dtls_tls_session.nx_secure_tls_crypto_table;

    session_peer_set();

    /* A cookie under the current secret, to be checked.  */
    length = clienthello_build(clienthello, 0, 0, 0, 0, NX_NULL, 0, 0x32);
    verify_expect(clienthello, NX_SUCCESS, NX_FALSE, __LINE__);
    length = clienthello_build(clienthello, 0, 1, 1, 0, server_session -> nx_secure_dtls_cookie,
                               NX_SECURE_DTLS_COOKIE_LENGTH, 0x32);

    memcpy(&fake_crypto_table, original_table, sizeof(fake_crypto_table));
#if (NX_SECURE_TLS_TLS_1_2_ENABLED)
    fake_crypto_table.nx_secure_tls_handshake_hash_sha256_method = NX_NULL;
#else
    fake_crypto_table.nx_secure_tls_handshake_hash_sha1_method = NX_NULL;
#endif
    server_session -> nx_secure_dtls_tls_session.nx_secure_tls_crypto_table = &fake_crypto_table;

    /* Checking the returned cookie fails.  */
    verify_expect(clienthello, NX_SECURE_TLS_MISSING_CRYPTO_ROUTINE, NX_FALSE, __LINE__);

    /* Issuing a cookie fails, and the ClientHello is refused.  */
    length = clienthello_build(clienthello, 0, 0, 0, 0, NX_NULL, 0, 0x32);
    verify_expect(clienthello, NX_SECURE_TLS_MISSING_CRYPTO_ROUTINE, NX_FALSE, __LINE__);
    if (_nx_secure_dtls_process_clienthello(server_session, &clienthello[25], length - 25) == NX_SUCCESS)
    {
        ERROR_COUNTER();
    }

    /* Deriving the server's next secret fails.  */
    memset(master, 0x11, sizeof(master));
    nx_secure_dtls_server_cookie_secret_set(&dtls_server, master, sizeof(master));
    verify_expect(clienthello, NX_SECURE_TLS_MISSING_CRYPTO_ROUTINE, NX_FALSE, __LINE__);
    if (dtls_server.nx_dtls_server_cookie_ready != NX_FALSE)
    {
        ERROR_COUNTER();
    }

    server_session -> nx_secure_dtls_tls_session.nx_secure_tls_crypto_table = original_table;
    nx_secure_dtls_server_cookie_secret_set(&dtls_server, NX_NULL, 0);
}

static VOID test_thread_entry(ULONG thread_input)
{
UINT status;

    printf("NetX Secure Test:   DTLS Session Cookie Test...........................");

    status = nx_udp_socket_create(&client_ip, &raw_socket, "Raw socket", NX_IP_NORMAL,
                                  NX_DONT_FRAGMENT, 0x80, 16);
    status |= nx_udp_socket_bind(&raw_socket, RAW_PORT, NX_NO_WAIT);
    status |= nx_secure_dtls_server_create(&dtls_server, &server_ip, SERVER_PORT, NX_IP_PERIODIC_RATE,
                                           server_session_buffer, sizeof(server_session_buffer),
                                           &nx_crypto_tls_ciphers, server_metadata, sizeof(server_metadata),
                                           server_tls_packet_buffer, sizeof(server_tls_packet_buffer),
                                           server_connect_notify, server_receive_notify);
    memset(&server_local_certificate, 0, sizeof(server_local_certificate));
    status |= nx_secure_x509_certificate_initialize(&server_local_certificate,
                                                    test_device_cert_der, test_device_cert_der_len,
                                                    NX_NULL, 0, test_device_cert_key_der,
                                                    test_device_cert_key_der_len, NX_SECURE_X509_KEY_TYPE_RSA_PKCS1_DER);
    status |= nx_secure_dtls_server_local_certificate_add(&dtls_server, &server_local_certificate, 1);
    status |= nx_secure_dtls_server_start(&dtls_server);
    status |= nx_secure_dtls_session_create(&plain_session, &nx_crypto_tls_ciphers,
                                            plain_metadata, sizeof(plain_metadata),
                                            plain_tls_packet_buffer, sizeof(plain_tls_packet_buffer),
                                            0, NX_NULL, 0);
    if (status)
    {
        ERROR_COUNTER();
    }

    test_handshake();
    if (server_session != NX_NULL)
    {
        test_direct();
        test_crypto_failures();
        nx_secure_dtls_session_reset(server_session);
    }

    nx_secure_dtls_session_delete(&plain_session);
    nx_udp_socket_unbind(&raw_socket);
    nx_udp_socket_delete(&raw_socket);
    nx_secure_dtls_server_stop(&dtls_server);
    nx_secure_dtls_server_delete(&dtls_server);

    if ((server_pool.nx_packet_pool_available != server_pool.nx_packet_pool_total) ||
        (client_pool.nx_packet_pool_available != client_pool.nx_packet_pool_total))
    {
        ERROR_COUNTER();
    }

    if (error_counter)
    {
        printf("ERROR!\n");
        test_control_return(1);
    }
    else
    {
        printf("SUCCESS!\n");
        test_control_return(0);
    }
}

